import{_ as p,a0 as r,w as l,s as m,ao as a,I as o,x as t,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"Gedit插件：Embedded Terminal，讓你在編輯器內使用命令列終端 | LCTT x X-CMD","titleTemplate":false,"description":"Gedit插件：Embedded Terminal，讓你在編輯器內使用命令列終端 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Gedit插件：Embedded Terminal，讓你在編輯器內使用命令列終端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Gedit插件：Embedded Terminal，讓你在編輯器內使用命令列終端 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Embedded Terminal – A Gedit Plugin To Access The Command Line Terminal From Within The Editor Window","title":"Gedit插件：Embedded Terminal，讓你在編輯器內使用命令列終端","tag":"201310","desc":""},"relativePath":"201310/Embedded Terminal – A Gedit Plugin To Access The Command Line Terminal From Within The Editor Window.md","filePath":"[post].md"}'),s={name:"201310/Embedded Terminal – A Gedit Plugin To Access The Command Line Terminal From Within The Editor Window.md"};function g(u,e,T,b,c,f){const d=r("Link");return l(),m("div",null,[e[11]||(e[11]=a(`<h1 id="gedit插件-embedded-terminal-讓你在編輯器內使用命令列終端" tabindex="-1">Gedit插件：Embedded Terminal，讓你在編輯器內使用命令列終端 <a class="header-anchor" href="#gedit插件-embedded-terminal-讓你在編輯器內使用命令列終端" aria-label="Permalink to “Gedit插件：Embedded Terminal，讓你在編輯器內使用命令列終端”">​</a></h1><p>有時候在Linux上使用基於GUI的程序，你必須在程序窗口和命令列窗口之間切換。這會消耗一些時間。將一個終端窗口嵌入到程序窗口內部是個很好的解決方案。我不知道在其他程序是否可以，但是，如果你為gedit尋找一個這樣的解決方案，那麼這兒有一個插件-- <strong>Embedded Terminal</strong> -- 能讓你從gedit窗口內部訪問命令列終端。</p><p><strong>NOTE</strong> -- 這篇文章中使用UbUntu 13.04作為例子。</p><p>###簡短教程</p><p>安裝了這個插件後，可以讓用户很容易地在編輯文件的同時訪問命令列。</p><p>這是插件啓用後的gedit窗口截圖：</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-embedded-terminal-colored.png" alt=""></p><p>如上，你可以看到在gedit窗口內部命令列操作與編輯文本文件集成到了一起。</p><p>###下載/安裝</p><p>通過以下步驟來正確地在gedit下載安裝和配置embedded terminal插件。</p><p><strong>步驟1</strong></p><p>通過命令安裝gedit插件：</p><pre><code>sudo apt-get install gedit-plugins
</code></pre><p><strong>步驟2</strong></p><p>現在，在gedit窗口裏，轉到Edit（編輯）--&gt;Preferences（首選項）--&gt;Plugins（插件）並且啓動Embedded Terminal插件。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-embedded-terminal-enable.png" alt=""></p><p><strong>步驟3</strong></p><p>在gedit窗口中點擊View（視圖）--&gt;Bottom Panel（底部面板）</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-view-bottom-panel.png" alt=""></p><p>你將在gedit窗口的底部面板看到一個嵌入式終端呈現出來。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-default-embedded-terminal.png" alt=""></p><p>唯一的問題是色調搭配不是很好，比如，白色的命令提示符在淡灰色背景下幾乎看不清。接下來的步驟去修改色調搭配。</p><p><strong>步驟4</strong></p><p>打開dconf-editor，如果沒有安裝，通過命令來安裝它：</p><pre><code>sudo apt-get install dconf-tools
</code></pre><p>安裝後，用下面命令來執行：</p><pre><code>dconf-editor
</code></pre><p>在dconf editor窗口中，轉到org--&gt;gnome--&gt;gedit--&gt;plugins--&gt;terminal並且取消選定use-theme-colors選項。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-dconf-settings.png" alt=""></p><p><strong>步驟5</strong></p><p>重啓gedit</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-embedded-terminal-colored.png" alt=""></p><p>可以看到，在淺色背景下的黑色的命令提示符。</p><p><strong>優點</strong></p><ul><li>從gedit窗口內部輕鬆訪問終端</li><li>作為一個插件，它能節約任何時間</li></ul><p><strong>缺點</strong></p><ul><li>在初始化配置裏色調搭配問題是個主要問題（譯註，估計插件作者使用的深色配色方案的Gedit，因此沒有意識到這個問題，期待以後的更新版本會解決這個問題）</li></ul><p><strong>總結</strong></p><p>無論如何，在Linux中工作總是難以避開命令列。所以，在你常用的程序窗口中嵌入一個終端是一個好多的方法。這個gedit插件是個不錯的小工具，它可以幫你節省一些時間。嘗試它，它值得你安裝。</p><hr>`,40)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),n(d,{href:"http://mylinuxbook.com/embedded-terminal-a-gedit-plugin/"},{default:i(()=>[...e[0]||(e[0]=[t("http://mylinuxbook.com/embedded-terminal-a-gedit-plugin/",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("本文由 ",-1)),n(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[2]||(e[2]=[t("LCTT",-1)])]),_:1}),e[5]||(e[5]=t(" 原創翻譯，",-1)),n(d,{href:"http://linux.cn/portal.php"},{default:i(()=>[...e[3]||(e[3]=[t("Linux中國",-1)])]),_:1}),e[6]||(e[6]=t(" 榮譽推出",-1))]),o("p",null,[e[9]||(e[9]=t("譯者：",-1)),n(d,{href:"http://linux.cn/space/Vito"},{default:i(()=>[...e[7]||(e[7]=[t("Vito",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),n(d,{href:"http://linux.cn/space/wxy"},{default:i(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})])])}const h=p(s,[["render",g]]);export{E as __pageData,h as default};
